// Retry Builder (Prompt Tweaks) — v2.1 (EACH; preserves envelope)
// Builds compact preface using pose + style + color + skin tone signals.
// NOW: Preserves all upstream fields for SW1 compatibility.
// - Uses retryAttempt/retryTag from upstream (Bump & Gate) when present; otherwise generates.
// - Prefers numeric skinToneScore/Threshold; falls back to legacy reasons if needed.
// - Output includes full envelope + retry-specific fields.

const j = $json || {};
const b = $binary || {};

/* ---------------- helpers ---------------- */
function asInt(v){ const n = Number(v); return Number.isFinite(n) ? Math.floor(n) : null; }
function bool(v){ if (typeof v === 'boolean') return v; if (typeof v === 'number') return v !== 0; if (typeof v === 'string') return /^(true|yes|y|1)$/i.test(v.trim()); return false; }
function byteLen(obj){ try { return Buffer.byteLength(typeof obj === 'string' ? obj : JSON.stringify(obj), 'utf8'); } catch { return -1; } }
function pad2(n){ n = Number(n); return Number.isFinite(n) ? String(n).padStart(2,'0') : ''; }
function num(v){ const n = Number(v); return Number.isFinite(n) ? n : null; }

/* ---------------- retry meta ---------------- */
const retryAttempt = asInt(j.retryAttempt) ?? asInt(j.qaRetry) ?? asInt(j.retryTry) ?? 1;
const ensureTag = () => (Math.random().toString(36).slice(2, 8) + Math.random().toString(36).slice(2, 4)).toUpperCase();
const retryTag = (typeof j.retryTag === 'string' && j.retryTag.length > 0) ? j.retryTag : `${retryAttempt}-${ensureTag()}`;

/* ---------------- derive identity ---------------- */
function pickCharHash(){ return j.characterHash || j.characterSpecs?.hash || j.__meta?.characterHash || null; }
function pickPoseNum(){ const n = Number(j.poseNumber ?? j.currentPoseNumber ?? j.__meta?.poseNumber); return Number.isFinite(n) ? n : null; }
const characterHash = pickCharHash();
const poseNumber = pickPoseNum();

/* ---------------- collect QA signals ---------------- */
// Pose hints (from earlier nodes)
const src = j.qaHints ?? j.qaVerdict ?? {};
const v = {
  pose_score:            (typeof src.pose_score === 'number') ? src.pose_score : null,
  single_subject:        bool(src.single_subject),
  extra_limbs:           bool(src.extra_limbs),
  bg_white:              bool(src.bg_white),
  leakage_from_pose_ref: bool(src.leakage_from_pose_ref),
  cropped:               bool(src.cropped)
};

// Style/Color metrics + thresholds
const styleQaScore  = (j.styleQaScore != null) ? Number(j.styleQaScore) : (j.qa?.style?.score?.style ?? null);
const colorQaScore  = (j.colorQaScore != null) ? Number(j.colorQaScore) : (j.qa?.style?.score?.color ?? null);
const styleThresh   = (j.styleQaThreshold != null) ? Number(j.styleQaThreshold) : (j.qa?.style?.threshold?.style ?? null);
const colorThresh   = (j.colorQaThreshold != null) ? Number(j.colorQaThreshold) : (j.qa?.style?.threshold?.color ?? null);

// Skin tone numeric inputs (preferred)
const skinToneScore = (j.skinToneScore != null) ? Number(j.skinToneScore) : (j.qa?.style?.score?.skin_tone ?? null);
const skinToneThr   = (j.skinToneThreshold != null) ? Number(j.skinToneThreshold) : (j.qa?.style?.threshold?.skin_tone ?? null);

// Reasons (legacy strings)
const reasons = Array.isArray(j.qaReasons) && j.qaReasons.length
  ? j.qaReasons
  : (Array.isArray(j.qa?.style?.reasons) ? j.qa.style.reasons : []);
const has = (key) => reasons.includes(key);

// Derived flags
const styleLow    = Number.isFinite(styleQaScore) && Number.isFinite(styleThresh) && styleQaScore < styleThresh;
const colorLow    = Number.isFinite(colorQaScore) && Number.isFinite(colorThresh) && colorQaScore < colorThresh;
const skinToneLow = Number.isFinite(skinToneScore) && Number.isFinite(skinToneThr) && skinToneScore < skinToneThr;

// Hair color mismatch (prefer boolean in qa.style; fallback to reason tag)
const hairMismatch = (j.qa?.style?.hair_color_match === false) || has('hair_color_mismatch') || has('hair_color_below_0.75');

/* ---------------- build preface ---------------- */
const pre = [];
pre.push(`[RETRY #${retryAttempt} | tag:${retryTag}]`);
pre.push('Follow POSE LOCK (IMAGE P) over all other guidance. Use IMAGE A for appearance only.');

// Pose corrections
if (v.pose_score !== null && v.pose_score < 0.9) pre.push('CRITICAL: Match IMAGE P pose EXACTLY (limbs, contact, orientation).');
if (v.extra_limbs || !v.single_subject) pre.push('STRICT: Exactly one character; exactly 2 arms, 2 legs, 2 shoes.');
if (!v.bg_white) pre.push('BACKGROUND: Pure white (#FFFFFF), no shadows/gradients/textures.');
if (v.cropped) pre.push('FRAMING: Full body visible; do not crop head/hands/feet.');
if (v.leakage_from_pose_ref) pre.push('APPEARANCE: Ignore appearance in IMAGE P; appearance comes ONLY from IMAGE A.');

// Style corrections
if (styleLow || has('line_style_mismatch')) {
  pre.push('STYLE: Match line weight and outline exactly as IMAGE A (flat 2D, no gradients/textures).');
}

// Color corrections (numeric preferred; legacy fallback)
if (colorLow || has('palette_shift') || has('saturation_shift')) {
  pre.push('COLOR: Use ONLY the palette from IMAGE A; do not introduce new hues.');
  pre.push('COLOR: Match saturation to IMAGE A; avoid over/under-saturation and any filters.');
}

// Skin tone correction (numeric preferred; legacy fallback)
if (skinToneLow || has('skin_tone_mismatch')) {
  pre.push('APPEARANCE: Match skin tone to IMAGE A exactly (no darkening/lightening or hue shift).');
}

// Hair color correction
if (hairMismatch) {
  pre.push('APPEARANCE: Hair color must match IMAGE A (or IMAGE B if provided) exactly — no hue/value shift.');
}

// Validator note last (kept short)
const validatorNote = (typeof j.qaNotes === 'string' && j.qaNotes) ? j.qaNotes : undefined;
if (validatorNote) pre.push(`Validator notes: ${String(validatorNote).slice(0,180)}`);

const posePromptPreface = pre.join('\n') + '\n\n';

/* ---------------- temperature/backoff ---------------- */
const baseTemp = (j.generationConfig && typeof j.generationConfig.temperature === 'number')
  ? j.generationConfig.temperature
  : (typeof j.temperature === 'number' ? j.temperature : 0.25);
const retryTemp = (typeof j.retryTemp === 'number') ? j.retryTemp : Math.max(0.10, Number(baseTemp) - 0.10);

/* ---------------- normalize hair field names for SW1 ---------------- */
// SW1 expects hairRefS3Key/hairRefPublicUrl, not hairKey/hairUrl
const hairRefS3Key = j.hairRefS3Key || j.hairKey || null;
const hairRefPublicUrl = j.hairRefPublicUrl || j.hairUrl || null;

/* ---------------- output: preserve all + add retry fields ---------------- */
const outJson = {
  ...j, // Preserve entire upstream envelope

  // Override/add retry-specific fields
  characterHash,
  poseNumber,
  currentPoseNumber: poseNumber,

  posePromptPreface, // NEW: retry instructions
  retryAttempt,      // Explicit retry counter
  retryTag,          // Unique retry identifier
  retryTemp,         // Adjusted temperature

  // Normalize hair fields for SW1
  hairRefS3Key,
  hairRefPublicUrl,

  // Preserve QA hints for debugging
  qaHints: {
    pose_score: v.pose_score,
    single_subject: v.single_subject,
    extra_limbs: v.extra_limbs,
    bg_white: v.bg_white,
    leakage_from_pose_ref: v.leakage_from_pose_ref,
    cropped: v.cropped
  },

  // Mirror metrics for downstream/debug (don't override if already present)
  styleQaScore: j.styleQaScore ?? (Number.isFinite(styleQaScore) ? styleQaScore : undefined),
  colorQaScore: j.colorQaScore ?? (Number.isFinite(colorQaScore) ? colorQaScore : undefined),
  styleQaThreshold: j.styleQaThreshold ?? (Number.isFinite(styleThresh) ? styleThresh : undefined),
  colorQaThreshold: j.colorQaThreshold ?? (Number.isFinite(colorThresh) ? colorThresh : undefined),
  skinToneScore: j.skinToneScore ?? (Number.isFinite(skinToneScore) ? skinToneScore : undefined),
  skinToneThreshold: j.skinToneThreshold ?? (Number.isFinite(skinToneThr) ? skinToneThr : undefined),

  qaReasons: j.qaReasons ?? (reasons.length ? reasons.slice(0,12) : undefined)
};

// Size logs (safe to remove later)
try {
  console.log({
    node: 'Retry Builder (Prompt Tweaks) v2.1',
    itemIndex: (typeof $itemIndex === 'number') ? $itemIndex : null,
    posePromptPreface_bytes: byteLen(posePromptPreface),
    outJson_bytes: byteLen(outJson),
    preserved_fields: Object.keys(outJson).length,
    hairRefS3Key_present: !!hairRefS3Key,
    hairRefPublicUrl_present: !!hairRefPublicUrl
  });
} catch {}

return { json: outJson, binary: b, ...( $input?.item?.pairedItem ? { pairedItem: $input.item.pairedItem } : {} ) };

// Bump & Gate QA Retry — EACH (normalized + idempotent) — v1.1
// Place this as the FIRST node on the retry branch.
// Changes vs your version:
// - Idempotency guard: avoids double-increment on resume/re-run of the same attempt.
// - Stronger MAX_RETRIES parsing + `retriesRemaining` convenience field.
// - Richer `retryTag` (still short) that can embed character/pose context; preserves a preexisting tag when staying in the same attempt.
// - Extra telemetry in __meta.bumpGate.

const j = $json || {};
const b = $binary || {};

function asInt(v){ const n = Number(v); return Number.isFinite(n) ? Math.floor(n) : null; }

function makeTag(attempt){
  const entropy = (Math.random().toString(36).slice(2, 8) + Math.random().toString(36).slice(2, 4)).toUpperCase();
  const shortId = j.characterHash ? String(j.characterHash).slice(0,6).toUpperCase() : '';
  const poseNN  = (typeof j.poseNumber === 'number') ? String(j.poseNumber).padStart(2,'0') : (j.poseNN ? String(j.poseNN).replace(/[^0-9]/g,'').padStart(2,'0') : '');
  // Example: 1-AB12CD34-569C50-P01
  return `${attempt}-${entropy}${shortId ? `-${shortId}` : ''}${poseNN ? `-P${poseNN}` : ''}`;
}

const MAX_RETRIES = asInt(j.maxPoseRetries) ?? asInt(j.qaMaxTries) ?? 3;

// Consider multiple sources to determine previous attempt
const prevCandidates = [
  asInt(j.retryAttempt),
  asInt(j.__meta?.qaRetry),
  asInt(j.qaRetry),
  asInt(j.retryTry),
  (asInt(j.__meta?.bumpGate?.next) ? asInt(j.__meta?.bumpGate?.next) - 1 : null),
].filter(v => Number.isFinite(v));

const prev = prevCandidates.length ? Math.max(...prevCandidates) : 0;
const plannedNext = asInt(j.__meta?.bumpGate?.next);

// Default bump
let next = prev + 1;

// Idempotency: if upstream shows we're already on this attempt (plannedNext === j.retryAttempt), don't bump again
if (plannedNext && asInt(j.retryAttempt) === plannedNext) {
  next = plannedNext; // stay on the same attempt
}

const withinLimit = next <= MAX_RETRIES;
const retriesRemaining = Math.max(0, MAX_RETRIES - (next - 1));

// Keep existing tag when we remain on the same attempt; otherwise generate new
const keepExistingTag = (asInt(j.retryAttempt) === next) && typeof j.retryTag === 'string' && j.retryTag.length > 0;
const retryTag = keepExistingTag ? j.retryTag : makeTag(next);

return {
  json: {
    ...j,
    // canonical
    retryAttempt: next,
    retryTag,
    // compat
    qaRetry: next,
    maxPoseRetries: MAX_RETRIES,
    // branch helpers
    hasRetriesRemaining: withinLimit,
    shouldRetry: withinLimit,
    __shouldRetry: withinLimit, // legacy
    isRetry: next > 0,
    retriesRemaining,

    __meta: {
      ...(j.__meta || {}),
      qaRetry: next,
      qaMaxTries: MAX_RETRIES,
      bumpGate: { prev, next, withinLimit, plannedNext, retriesRemaining }
    },
  },
  binary: b,
  pairedItem: $input?.item?.pairedItem ?? { item: ($itemIndex ?? 0) },
};

// QA Handoff — Purge & Keep Keys (Initial → QA) — v2.3 (hair refs + stable poseNN + no empty-string traps)
// Goal: drop ALL binaries, keep durable identifiers/URLs so QA+Retry can rehydrate.
// Preserves retryAttempt/retryTag (normalized), QA signals, contract keys.
// v2.3: 
//  - Preserve hairRefS3Key/hairRefPublicUrl and map them to hairKey/hairUrl if those aren’t present
//  - Don’t mutate incoming poseNN; also expose poseNN_plain and poseNN_hyphen
//  - Treat "" as empty for URL fallbacks (e.g., baseRefPublicUrl)
//  - Default posesPublicBase to your canonical characters/poses root
//  - Keep temperature/topK/topP from generationConfig when present
//  - Sanitize paths and support weird "publicR2Url (String):" input key

const jIn  = $json || {};
const bIn  = $binary || {};
const runIx = (typeof $runIndex === 'number') ? $runIndex : 0;
const ix    = (typeof $itemIndex === 'number') ? $itemIndex : 0;

/* ---------------- helpers ---------------- */
function clamp(n){ n = Number(n); return Number.isFinite(n) ? Math.max(1, Math.min(99, Math.floor(n))) : null; }
function pad2(n){ n = Number(n); return Number.isFinite(n) ? String(n).padStart(2,'0') : null; }
function parsePoseFromString(s){
  if (!s) return null;
  const m = String(s).match(/pose[_-]?(\d{1,2})(?:\.(?:png|jpe?g|webp))?$/i) || String(s).match(/(?:^|[^\d])(\d{1,2})(?:\.(?:png|jpe?g|webp))?$/i);
  return m ? clamp(m[1]) : null;
}
function asInt(v){ const n = Number(v); return Number.isFinite(n) ? Math.floor(n) : null; }
function asBool(v){
  if (v === true) return true;
  if (v === false || v == null) return false;
  if (typeof v === 'number') return v === 1;
  if (typeof v === 'string'){
    const s = v.trim().toLowerCase();
    if (/^(true|1|yes|y|on)$/.test(s)) return true;
    if (/^(false|0|no|n|off)$/.test(s)) return false;
  }
  return false;
}
function isNonEmpty(v){
  if (v === null || v === undefined) return false;
  if (typeof v === 'string') return v.trim().length > 0;
  return true; // numbers/booleans/objects considered non-empty
}
function firstNonEmpty(){ for (let i=0;i<arguments.length;i++){ const v = arguments[i]; if (isNonEmpty(v)) return v; } return undefined; }
function sanitizePath(s){ return String(s || '').replace(/\/{2,}/g,'/').replace(/\/+$/,''); }

/* ---------------- identities ---------------- */
const orderId        = jIn.orderId ?? jIn.amazonOrderId ?? jIn.meta?.orderId ?? null;
const characterHash  = firstNonEmpty(jIn.characterHash, jIn.__meta?.deriveQaPass?.snapshot?.characterHash, null);

let poseNumber = clamp(
  jIn.poseNumber ?? jIn.currentPoseNumber ??
  jIn.__meta?.poseNumber ?? parsePoseFromString(jIn.poseRefName)
);

// Keep incoming poseNN if provided; also compute plain + hyphen variants for convenience
const poseNN_in      = (typeof jIn.poseNN === 'string' && jIn.poseNN.trim()) ? jIn.poseNN.trim() : null;
const poseNN_plain   = poseNumber ? `pose${pad2(poseNumber)}` : (poseNN_in ? poseNN_in.replace(/-/g,'') : null);
const poseNN_hyphen  = poseNumber ? `pose-${pad2(poseNumber)}` : (poseNN_in ? poseNN_in.replace(/^pose/,'pose-') : null);
const poseNN         = poseNN_in || poseNN_plain;

const poseKey  = jIn.poseKey ?? (orderId && characterHash && poseNN ? `${orderId}|${characterHash}|${poseNN}` : null);

/* ---------------- retry meta (normalized) ---------------- */
const retryAttempt = asInt(jIn.retryAttempt) ?? asInt(jIn.qaRetry) ?? asInt(jIn.retryTry) ?? 0; // 0 before first retry
const retryTag     = firstNonEmpty(jIn.retryTag, null);

/* ---------------- contract spaces & URLs ---------------- */
// Some inputs arrived as `publicR2Url (String):` — support that too.
const publicR2UrlIn = firstNonEmpty(jIn.publicR2Url, jIn['publicR2Url (String):'], 'https://pub-92cec53654f84771956bc84dfea65baa.r2.dev');
const publicRoot    = sanitizePath(publicR2UrlIn);

const assetsRootIn  = firstNonEmpty(jIn.assetsRoot, 'book-mvp-simple-adventure/order-generated-assets');
const assetsRoot    = sanitizePath(assetsRootIn);

const templatePathIn = firstNonEmpty(jIn.templatePath, 'templates');
const tpl            = sanitizePath(templatePathIn);

// Canonical default (matches your SW2): characters/poses under book-mvp...
const posesPublicBase = sanitizePath(firstNonEmpty(jIn.posesPublicBase, 'book-mvp-simple-adventure/characters/poses'));

// compute/normalize durable keys (with strong fallbacks)
const baseCharacterKey = firstNonEmpty(
  jIn.baseCharacterKey,
  jIn.__meta?.baseUploadKey,
  jIn.__meta?.storageKey,
  (characterHash && assetsRoot ? `${assetsRoot}/characters/${characterHash}/base-character.png` : null)
);

// IMPORTANT: treat "" as empty; fall back to computed public URL when needed
const baseRefPublicUrl = firstNonEmpty(
  jIn.baseRefPublicUrl,
  jIn.baseCharacterUrl,
  (baseCharacterKey ? `${publicRoot}/${baseCharacterKey}` : null)
);

// Keep provided poseRefKey/Url; otherwise compute using existing convention (no hyphen)
// (We don’t force-switch naming conventions here to avoid breaking callers.)
const poseRefKey = firstNonEmpty(
  jIn.poseRefKey,
  (poseNumber ? `${posesPublicBase}/pose${pad2(poseNumber)}.png` : null)
);
const poseRefPublicUrl = firstNonEmpty(
  jIn.poseRefPublicUrl,
  jIn.poseRefUrl,
  (poseRefKey ? `${publicRoot}/${poseRefKey}` : null)
);

// Hair references: preserve both the "ref" fields and map to hairKey/hairUrl when explicit fields aren’t present
const hairRefS3Key     = firstNonEmpty(jIn.hairRefS3Key, jIn.hairS3Key, null);
const hairRefPublicUrl = firstNonEmpty(jIn.hairRefPublicUrl, jIn.hairPublicUrl, null);

const hairKey = firstNonEmpty(jIn.hairKey, hairRefS3Key, null);
const hairUrl = firstNonEmpty(jIn.hairUrl, hairRefPublicUrl, null);

// parse hairPromptMeta to a real object
let hairPromptMeta = jIn.hairPromptMeta;
if (typeof hairPromptMeta === 'string') {
  try { hairPromptMeta = JSON.parse(hairPromptMeta); } catch { hairPromptMeta = {}; }
}
if (!hairPromptMeta || typeof hairPromptMeta !== 'object') hairPromptMeta = {};

/* ---------------- generation config passthrough ---------------- */
let generationConfig;
if (jIn.generationConfig && typeof jIn.generationConfig === 'object') {
  const g = jIn.generationConfig;
  generationConfig = {
    imageConfig: g.imageConfig,
    temperature: g.temperature,
    // keep these if present; don’t invent defaults
    ...(typeof g.topK === 'number' ? { topK: g.topK } : {}),
    ...(typeof g.topP === 'number' ? { topP: g.topP } : {}),
  };
}

/* ---------------- build lean handoff JSON ---------------- */
const keep = {
  // routing / identity
  orderId,
  amazonOrderId: jIn.amazonOrderId ?? null,
  correlationId: jIn.correlationId ?? null,
  characterHash,
  poseNumber: poseNumber ?? null,
  currentPoseNumber: poseNumber ?? jIn.currentPoseNumber ?? null,
  poseNN,                 // preserve input if provided
  poseNN_plain,           // convenience (pose09)
  poseNN_hyphen,          // convenience (pose-09)
  poseIndex: jIn.poseIndex ?? null,
  poseKey,
  generatedFileName: jIn.generatedFileName ?? null,

  // spaces
  assetsRoot,
  publicR2Url: publicRoot,
  templatePath: tpl,
  posesPublicBase,

  // prompt state for Retry Builder
  posePromptBlock: String(jIn.posePromptBlock || ''),
  model: jIn.model || jIn.modelVersion || null,
  generationConfig,

  // hairstyle context that downstream prompt builders read
  hairPromptMeta,
  hairStyleCanonical: jIn.hairStyleCanonical ?? hairPromptMeta.styleKey ?? null,
  clothingTypeCanonical: jIn.clothingTypeCanonical ?? hairPromptMeta.clothingTypeCanonical ?? null,

  // QA signals (kept lean; may be empty on first pass)
  qaThreshold: (Number.isFinite(Number(jIn.qaThreshold)) ? Number(jIn.qaThreshold) : 0.70),
  styleQaThreshold: Number.isFinite(Number(jIn.styleQaThreshold)) ? Number(jIn.styleQaThreshold) : undefined,
  colorQaThreshold: Number.isFinite(Number(jIn.colorQaThreshold)) ? Number(jIn.colorQaThreshold) : undefined,
  skinToneThreshold: Number.isFinite(Number(jIn.skinToneThreshold)) ? Number(jIn.skinToneThreshold) : undefined,
  qaReasons: Array.isArray(jIn.qaReasons) ? jIn.qaReasons.slice(0, 12) : null,
  qaHints: jIn.qaHints || null,
  qaNotes: (typeof jIn.qaNotes === 'string') ? jIn.qaNotes : undefined,
  qaPass: asBool(jIn.qaPass ?? jIn.qaCombinedPass) || false,
  qaScore: Number.isFinite(Number(jIn.qaScore)) ? Number(jIn.qaScore) : (jIn.qaVerdict?.pose_score ?? null),
  qaPolicy: jIn.qaPolicy ?? jIn.qa?.combined?.policy ?? null,

  // retry meta (normalized + legacy)
  retryAttempt,
  retryTag: retryTag ?? undefined,
  qaRetry: retryAttempt,
  maxPoseRetries: jIn.maxPoseRetries ?? jIn.qaMaxTries ?? 3,

  // DURABLE keys/urls so downstream can rehydrate without carrying binaries
  baseCharacterKey,
  baseRefPublicUrl,                   // canonical
  baseCharacterUrl: baseRefPublicUrl, // alias for older nodes

  poseRefKey,
  poseRefPublicUrl,                   // canonical
  poseRefUrl: poseRefPublicUrl,       // alias
  poseRefName: jIn.poseRefName ?? null,

  // hair references (preserve both original ref fields and mapped convenience keys)
  hairRefS3Key,
  hairRefPublicUrl,
  hairKey,
  hairUrl,

  // routing flags
  __route: jIn.__route ?? (asBool(jIn.__testMode || jIn.testMode) ? 'TEST' : 'REAL'),
  __testMode: asBool(jIn.__testMode || jIn.testMode || jIn.__meta?.__testMode || jIn.ctx?.__testMode || jIn.ctx?.testMode),
  testMode:  asBool(jIn.__testMode || jIn.testMode || jIn.__meta?.__testMode || jIn.ctx?.__testMode || jIn.ctx?.testMode),

  // breadcrumb
  __meta: {
    ...(jIn.__meta || {}),
    qahandoff: { runIx, itemIndex: ix, stripped: true }
  }
};

// Output: NO binaries.
if (global.gc) { try { global.gc(); } catch {} }
return { json: keep, binary: {} };

// Entry Shim — Normalize Defaults + Pin Keys (EACH) — v1.1
// Replaces env access; computes baseCharacterKey/baseRefPublicUrl/poseRefKey/poseRefPublicUrl
// Parses hairPromptMeta if string; preserves clothing/hair canonicals.
// FIX: Standardized to pose-${NN}.png (hyphenated)

const jIn = $json || {};
const bIn = $binary || {};

// helpers
const pick = (...v) => v.find(x => x !== undefined && x !== null && x !== '');
const num = (v,d)=> Number.isFinite(+v) ? +v : d;
const pad2 = (n)=> String(n).padStart(2,'0');

// test flag from JSON only
const isTest = !!(jIn.__testMode || jIn.testMode || jIn.__meta?.__testMode || jIn.ctx?.__testMode || jIn.ctx?.testMode);

// carry/derive basics
const ctxIn = jIn.ctx || {};
const characterHash = pick(jIn.characterHash, ctxIn.characterHash, jIn.__meta?.characterHash, null);

const assetsRoot   = jIn.assetsRoot   || 'book-mvp-simple-adventure/order-generated-assets';
const publicR2Url  = jIn.publicR2Url  || 'https://pub-92cec53654f84771956bc84dfea65baa.r2.dev';
const templatePath = jIn.templatePath || 'templates';

// pose number (if present)
const poseNum = Number.isFinite(+jIn.poseNumber) ? +jIn.poseNumber
               : Number.isFinite(+jIn.currentPoseNumber) ? +jIn.currentPoseNumber
               : null;

// pin keys
const baseCharacterKey = jIn.baseCharacterKey
  || jIn.__meta?.baseUploadKey
  || jIn.__meta?.storageKey
  || (characterHash ? `${assetsRoot}/characters/${characterHash}/base-character.png` : null);

// FIX: Standardize to pose-${NN}.png
const poseRefKey = jIn.poseRefKey
  || (poseNum ? `${String(templatePath).replace(/\/+$/,'')}/poses/pose-${pad2(poseNum)}.png` : null);

// public URLs
const baseRefPublicUrl = baseCharacterKey ? `${publicR2Url}/${baseCharacterKey}` : jIn.baseRefPublicUrl;
const poseRefPublicUrl = poseRefKey ? `${publicR2Url}/${poseRefKey}` : jIn.poseRefPublicUrl;

// hair meta (string or object)
let hairPromptMeta = jIn.hairPromptMeta;
if (typeof hairPromptMeta === 'string') {
  try { hairPromptMeta = JSON.parse(hairPromptMeta); } catch {}
}
const hairStyleCanonical = jIn.hairStyleCanonical || hairPromptMeta?.styleKey || jIn.characterSpecs?.hairStyle || null;
const clothingTypeCanonical = jIn.clothingTypeCanonical || jIn.characterSpecs?.clothingStyle || null;

// normalization for counts
const numPoses       = num(pick(jIn.totalPosesRequired, jIn.numPoses), 12);
const maxPoseRetries = num(pick(jIn.maxPoseRetries, jIn.maxRetries), 3);

// build out json
const out = {
  ...jIn,
  ctx: { ...ctxIn, characterHash },
  characterHash,
